<template>
	<view :style="{ '--mobile-header-height': headerHeight + 'px' }" class="delivery-page" :class="{'login-page':screen==='login'}">
		<MobileHeader ref="mobileHeader" @layout="headerHeight = $event" v-if="screen!=='login'&&screen!=='workbench'&&screen!=='alert'" :title="pageTitle" @back="goBack" />
		<view v-if="screen==='login'" class="login-screen"><image class="login-landscape" src="/static/design/spring-landscape.jpg" mode="aspectFill" aria-hidden="true"/><MobileHeader ref="mobileHeader" @layout="headerHeight = $event" :back="false" title="" transparent />
			<view class="login-brand"><image class="courier-mark" src="/static/spring-mark.svg" mode="aspectFit"/><text class="ui-strong">山泉配送</text><text>专注每一滴 · 服务每一单</text></view>
			<view class="login-form"><text class="integration-note">{{ appConfig.demoAuth ? '本地联调可使用演示账号；正式账号仍可使用密码登录' : '请使用后台分配的送水员手机号和密码登录' }}</text><view><AppIcon name="phone" size="30rpx" tone="muted"/><input v-model="phone" type="number" maxlength="11" placeholder="请输入已绑定手机号" /></view><view><AppIcon name="shield" size="30rpx" tone="muted"/><input v-model="password" password maxlength="64" placeholder="请输入登录密码" /></view><button :disabled="loginLoading" @click="login">{{ loginLoading ? '正在验证…' : '登录工作台' }}</button></view>
			<view class="current-station"><text>所属水站</text><view><AppIcon name="pin" size="29rpx"/><text class="ui-strong">{{courierProfile.station || '登录后自动识别'}}</text></view></view>
		</view>

		<template v-else-if="screen==='workbench'||screen==='alert'">
			<view class="work-hero"><MobileHeader ref="mobileHeader" @layout="headerHeight = $event" :back="false" title="" dark transparent /><view class="work-profile"><view class="avatar">{{(courierProfile.name || '送').slice(0,1)}}</view><view><text class="ui-strong">{{courierProfile.name || '送水员'}}</text><text>{{courierProfile.station || '水站待同步'}}</text></view><view class="online"><text>{{updatingOnline ? '同步中' : online ? '接单中' : '已暂停接单'}}</text><switch :checked="online" :disabled="updatingOnline" color="#68d8bf" @change="toggleOnline"/></view></view></view>
			<scroll-view scroll-y class="work-scroll">
				<view class="stats-card"><view class="today"><text>今日配送</text><text class="ui-strong">{{deliveryStats.total}}<text class="ui-small"> 单</text></text></view><view class="stat-grid"><view><text class="ui-strong">{{deliveryStats.pending}}</text><text>待配送</text></view><view><text class="ui-strong">{{deliveryStats.delivering}}</text><text>配送中</text></view><view><text class="ui-strong">{{deliveryStats.completed}}</text><text>已完成</text></view></view><view class="bar-stat"><text>配送桶数</text><text class="ui-strong">{{deliveryStats.barrels}}<text class="ui-small"> 桶</text></text></view></view>
				<view class="section-row"><text class="ui-strong">下一单任务</text><text @click="loadOrders(true)">刷新</text></view>
				<view v-if="nextOrder" class="next-card" @click="selectOrder(nextOrder)"><view><text class="ui-strong">{{nextOrder.customer}}</text><text class="status-chip">{{nextOrder.status}}</text></view><text>{{nextOrder.address}}</text><text class="ui-strong">{{nextOrder.deliveryWindow || nextOrder.timeLabel}} <text class="ui-small">{{nextOrder.deliveryWindow ? '配送时段' : '下单'}}</text></text><view><text>{{nextOrder.orderType==='补送' ? '补送单 · ' : ''}}{{nextOrder.spec}} · {{nextOrder.courierId ? '已由后台派单' : '等待派单'}}</text><text>›</text></view></view>
				<view v-else class="next-card"><view><text class="ui-strong">暂无配送任务</text><text class="status-chip">已同步</text></view><text>后台派单后会自动出现在这里</text></view>
				<view class="section-row"><text class="ui-strong">常用工具</text></view><view class="tools"><view @click="openTicketSign"><view class="tool-icon"><AppIcon name="ticket" size="31rpx" tone="light"/></view><text>上门收票</text></view><view @click="open('sign')"><view class="tool-icon"><AppIcon name="check" size="31rpx" tone="light"/></view><text>主动签收</text></view><view @click="callCustomer"><view class="tool-icon"><AppIcon name="phone" size="31rpx" tone="light"/></view><text>联系客户</text></view><view @click="navigateToCustomer"><view class="tool-icon"><AppIcon name="map" size="31rpx" tone="light"/></view><text>导航到客户</text></view></view>
				<view class="section-row"><text class="ui-strong">今日订单</text><text @click="navChange('orders')">全部订单 ›</text></view><view class="simple-order" v-for="o in todayOrders.slice(0,6)" :key="o.id" @click="selectOrder(o)"><view class="order-index">{{o.index}}</view><view><text class="ui-strong">{{o.customer}}</text><text>{{o.address}}</text></view><view><text class="ui-strong">{{o.timeLabel}}</text><text>{{o.status}}</text></view></view>
				<view v-if="!todayOrders.length" class="simple-order"><view class="order-index">–</view><view><text class="ui-strong">今日暂无订单</text><text>后台派单后会实时出现</text></view></view>
			</scroll-view>
			<BottomNav active="workbench" variant="delivery" :badge="activeOrderCount" @change="navChange"/>
			<view v-if="screen==='alert'" class="alert-layer"><view class="alert-card"><view class="bell"><AppIcon name="bell" size="50rpx" tone="light"/></view><text class="ui-strong">新订单已派送给您</text><text>请及时处理</text><view class="alert-info"><view><text>客户</text><text class="ui-strong">{{pendingOrder?.customer || '同步中'}}</text><AppIcon name="phone" size="26rpx"/></view><view><text>地址</text><text class="ui-strong">{{pendingOrder?.address || '同步中'}}</text></view><view><text>商品</text><text class="ui-strong">{{pendingOrder?.spec || '同步中'}}</text></view><view><text>订单号</text><text class="ui-strong">{{pendingOrder?.id || '同步中'}}</text><AppIcon name="pin" size="25rpx"/></view></view><button @click="acceptOrder">立即接单</button><text class="later" @click="open('workbench')">稍后处理（{{countdown}}s）</text></view></view>
		</template>

		<template v-else-if="screen==='orders'||screen==='messages'||screen==='mine'">
			<view class="work-hero compact"><view class="work-profile"><view class="avatar">{{(courierProfile.name || '送').slice(0,1)}}</view><view><text class="ui-strong">{{ {orders:'我的订单',messages:'消息动态',mine:'我的'}[screen] }}</text><text>{{courierProfile.name || '送水员'}} · {{courierProfile.station || '水站待同步'}}</text></view></view></view>
			<scroll-view scroll-y class="work-scroll">
				<template v-if="screen==='orders'">
					<view class="segment-row"><text v-for="tab in orderTabs" :key="tab" :class="{active:orderTab===tab}" @click="orderTab=tab">{{tab}}</text></view>
					<view class="simple-order" v-for="o in filteredOrders" :key="o.id" @click="selectOrder(o)"><view class="order-index">{{o.index}}</view><view><text class="ui-strong">{{o.customer}} · {{o.spec}}</text><text>{{o.address}}</text></view><view><text class="ui-strong">{{o.deliveryWindow || o.timeLabel}}</text><text>{{o.status}}</text></view></view>
					<view v-if="!filteredOrders.length" class="simple-order"><view class="order-index">–</view><view><text class="ui-strong">暂无{{orderTab==='全部'?'':orderTab}}订单</text><text>数据每 3 秒自动同步</text></view></view>
				</template>
				<template v-else-if="screen==='messages'">
					<view class="simple-order" v-for="m in messages" :key="m.key"><view class="order-index"><AppIcon name="bell" size="26rpx" tone="light"/></view><view><text class="ui-strong">{{m.title}}</text><text>{{m.orderId}} · {{m.customer}}</text></view><view><text class="ui-strong">{{m.time}}</text><text>{{m.status}}</text></view></view>
					<view v-if="!messages.length" class="simple-order"><view class="order-index">–</view><view><text class="ui-strong">暂无消息</text><text>派单、接单、签收都会记录在这里</text></view></view>
				</template>
				<template v-else>
					<view class="stats-card"><view class="today"><text>今日完成</text><text class="ui-strong">{{deliveryStats.completed}}<text class="ui-small"> 单</text></text></view><view class="stat-grid"><view><text class="ui-strong">{{deliveryStats.pending}}</text><text>待配送</text></view><view><text class="ui-strong">{{deliveryStats.delivering}}</text><text>配送中</text></view><view><text class="ui-strong">{{deliveryStats.barrels}}</text><text>桶数</text></view></view></view>
					<view class="mine-list"><view><text>姓名</text><text class="ui-strong">{{courierProfile.name || '送水员'}}</text></view><view><text>手机号</text><text class="ui-strong">{{courierProfile.phone || phone || '--'}}</text></view><view><text>所属水站</text><text class="ui-strong">{{courierProfile.station || '水站待同步'}}</text></view><view><text>接单提醒</text><text class="ui-strong">{{online ? '开启' : '已暂停'}}</text></view></view>
					<button class="logout-button" @click="logout">退出登录</button>
				</template>
			</scroll-view>
			<BottomNav :active="screen" variant="delivery" :badge="activeOrderCount" @change="navChange"/>
		</template>

		<scroll-view v-else-if="screen==='delivery-detail'" scroll-y class="detail-scroll">
			<view class="delivery-state"><view class="clock"><AppIcon name="clock" size="35rpx" tone="light"/></view><view><text class="ui-strong">{{activeOrder?.status || '配送中'}}</text><text>{{activeOrder?.dispatchStatus || '订单状态实时同步'}}</text></view></view>
			<view class="detail-card customer"><view><text>客户</text><text class="ui-strong">{{activeOrder?.customer || '暂无客户'}}</text><text>{{activeOrder?.phone || '--'}}</text></view><button @click="callCustomer"><AppIcon name="phone" size="32rpx"/></button></view>
			<view class="detail-card address-block"><view><text>地址</text><text class="ui-strong">{{activeOrder?.address || '暂无地址'}}</text><text v-if="activeOrder?.deliveryWindow" class="ui-small">配送时段 {{activeOrder.deliveryWindow}}</text></view><button aria-label="导航到客户地址" @click="navigateToCustomer"><AppIcon name="pin" size="30rpx"/><text class="ui-small">导航</text></button></view>
			<view class="detail-card"><text class="block-title">商品{{activeOrder?.orderType==='补送' ? '（售后补送单）' : ''}}</text><view class="product-line" v-for="line in activeLines" :key="line.lineNo"><WaterJug size="small" :label="line.product" :spec="line.spec"/><view><text class="ui-strong">{{line.product}}</text><text>{{line.spec}} × {{line.quantity}}{{line.ticketQuantity ? `（水票抵 ${line.ticketQuantity}）` : ''}}</text></view></view><view class="recycle"><text class="ui-span">配送数量</text><text class="ui-strong">× {{activeOrder?.quantity || 0}}</text></view><view class="recycle"><text class="ui-span">{{receivable.label}}</text><text class="ui-strong">{{receivable.value}}</text></view></view>
			<view v-if="activeOrder?.fulfillmentHoldReason" class="detail-card note"><text>暂停配送</text><text>{{activeOrder.fulfillmentHoldReason}}</text></view>
			<view class="detail-card note"><text>备注</text><text class="ui-strong">{{activeOrder?.remark || '无特殊备注'}}</text></view>
		</scroll-view>

		<scroll-view v-else-if="screen==='sign'" scroll-y class="detail-scroll sign-scroll">
			<text class="sign-label">选择签收方式</text><view class="sign-options"><view v-for="item in signOptions" :key="item.id" :class="{active:signMethod===item.id,unavailable:!item.available}" @click="item.available&&(signMethod=item.id)"><view class="sign-icon"><AppIcon :name="item.icon" size="30rpx"/></view><view><text class="ui-strong">{{item.name}}</text><text class="ui-small">{{item.note}}</text></view><text class="ui-span">{{signMethod===item.id?'✓':''}}</text></view></view>
			<view v-if="signMethod==='ticket'" class="ticket-form"><text class="sign-label">上门回收客户水票</text><view class="segment-row"><text :class="{active:ticketType==='纸质票'}" @click="ticketType='纸质票'">纸质票</text><text :class="{active:ticketType==='电子票'}" @click="ticketType='电子票'">电子票</text></view><view class="ticket-input"><input v-model="ticketCode" placeholder="输入水票编码，如 JT000238 / ET0001" confirm-type="done" @confirm="addTicket" /><button aria-label="扫码录入水票" @click="scanTicketCode"><AppIcon name="qr" size="26rpx" tone="light"/></button></view><button class="add-ticket" :disabled="ticketChecking" @click="addTicket">{{ticketChecking ? '校验中…' : '添加这张水票'}}</button><view v-for="(item,index) in collectTickets" :key="item.type + item.code" class="ticket-chip"><text>{{item.type}} {{item.code}}</text><text class="remove-ticket" @click="removeTicket(index)">移除</text></view><text class="ui-small">{{ticketPreview ? `收 ${collectTickets.length} 张水票后应收 ¥${Number(ticketPreview.amount).toFixed(2)}（水票抵 ¥${Number(ticketPreview.ticketAmount).toFixed(2)}）` : '每张水票抵一桶，签收时核销；差额当面收取'}}</text></view>
			<view v-if="signMethod==='scan'" class="ticket-form"><text class="sign-label">扫描客户签收二维码</text><view class="ticket-input"><input v-model="receiptCode" inputmode="numeric" maxlength="6" placeholder="扫描或输入 6 位签收码" /><button @click="scanReceiptCode"><AppIcon name="qr" size="26rpx" tone="light"/></button></view><text class="ui-small">签收码仅对该订单有效，服务端校验通过后才会完成签收</text></view>
			<text class="sign-label">送达凭证（可选，上传后随订单保存并同步给客户）</text><view class="proof-photo"><image v-if="proofLocalPath" :src="proofLocalPath" mode="aspectFill"/><view v-else class="proof-empty" @click="chooseProof"><AppIcon name="camera" size="54rpx" tone="muted"/><text>拍摄或上传送达照片</text><text class="ui-small">上传后，客户可在订单中查看</text></view><view class="retake" @click="chooseProof"><AppIcon name="camera" size="24rpx" tone="light"/><text>{{proofLocalPath?'重新拍照':'选择照片'}}</text></view></view><view class="confirm-check" @click="confirmed=!confirmed"><text class="ui-span" :class="{on:confirmed}">{{confirmed?'✓':''}}</text><text>已与客户沟通并完成送达</text></view>
		</scroll-view>

		<scroll-view v-else scroll-y class="detail-scroll"><view class="detail-card note"><text class="ui-strong">页面不存在</text><text>该入口已下线，请返回工作台继续配送</text><button class="add-ticket" @click="open('workbench')">返回工作台</button></view></scroll-view>

		<view v-if="screen==='delivery-detail'" class="double-action"><button class="ghost" @click="callCustomer">☎ 联系客户</button><button @click="open('sign')">确认送达</button></view>
		<view v-else-if="screen==='sign'" class="single-action"><button :disabled="signing" @click="finishSign">{{ signing ? '正在签收…' : (signMethod==='ticket' ? '收票并签收' : '确认签收') }}</button></view>
	</view>
</template>

<script>
import MobileHeader from '../../components/MobileHeader.vue'
import BottomNav from '../../components/BottomNav.vue'
import WaterJug from '../../components/WaterJug.vue'
import AppIcon from '../../components/AppIcon.vue'
import { waterApi } from '../../services/waterApi.js'

export default {
	components:{MobileHeader,BottomNav,WaterJug,AppIcon},
	data(){return{ headerHeight: 44,screen:'login',phone:'',password:'',loginLoading:false,appConfig:{demoAuth:false},countdown:15,countdownTimer:null,signMethod:'manual',confirmed:true,proofLocalPath:'',signing:false,ticketType:'纸质票',ticketCode:'',collectTickets:[],ticketPreview:null,ticketChecking:false,receiptCode:'',online:false,updatingOnline:false,orderTab:'全部',orderTabs:['全部','待配送','配送中','已完成'],refreshTimer:null,selectedOrder:null,knownPendingIds:[],courierProfile:{name:'',station:'',phone:''},
		orders:[]
	}},
	computed:{pageTitle(){return{'delivery-detail':'配送单详情',sign:this.signMethod==='ticket'?'上门收票签收':this.signMethod==='scan'?'扫码签收':'主动签收'}[this.screen]||''},
		/** 上门收票只适用于未付款的货到付款订单（已付款订单收票会重复收费） */
		ticketSignAvailable(){const order=this.activeOrder;return Boolean(order)&&order.orderType!=='补送'&&order.payment==='货到付款'&&order.payStatus==='未支付'},
		signOptions(){return [{id:'manual',icon:'camera',name:'送水员主动签收',note:'由送水员手动确认送达',available:true},{id:'ticket',icon:'ticket',name:'上门收票签收',note:this.ticketSignAvailable?'回收客户纸质票/电子票抵扣应收，差额当面收取':'仅未付款的货到付款订单可收票',available:this.ticketSignAvailable},{id:'scan',icon:'qr',name:'扫描签收码',note:'扫描客户订单详情中的签收二维码',available:true}]},
		activeLines(){const order=this.activeOrder;if(!order)return [];if(Array.isArray(order.items)&&order.items.length)return order.items;return [{lineNo:1,product:order.product,spec:order.spec,quantity:order.quantity,ticketQuantity:0}]},
		receivable(){const order=this.activeOrder;if(!order)return{label:'应收',value:'--'};if(order.orderType==='补送')return{label:'补送单',value:'免费，无需收款'};if(order.payment==='货到付款'&&order.payStatus==='未支付')return{label:'货到付款应收',value:`¥${Number(order.amount||0).toFixed(2)}`};return{label:order.payStatus==='已支付'?'已付款':'应收',value:`¥${Number(order.amount||0).toFixed(2)}（${order.payment}，无需收款）`}},pendingOrder(){return this.orders.find(order=>order.status==='待配送'&&!order.fulfillmentHoldReason)},nextOrder(){return this.orders.find(order=>order.status==='配送中'&&!order.fulfillmentHoldReason)||this.pendingOrder||this.orders[0]},activeOrder(){return this.selectedOrder||this.nextOrder},activeOrderCount(){return this.orders.filter(order=>['待配送','配送中'].includes(order.status)).length},filteredOrders(){return this.orderTab==='全部'?this.orders:this.orders.filter(order=>order.status===this.orderTab)},todayOrders(){const now=new Date();return this.orders.filter(order=>{const date=new Date(order.createdAt);return !Number.isNaN(date.getTime())&&date.getFullYear()===now.getFullYear()&&date.getMonth()===now.getMonth()&&date.getDate()===now.getDate()})},deliveryStats(){const today=this.todayOrders;return{total:today.length,pending:today.filter(order=>order.status==='待配送'&&!order.fulfillmentHoldReason).length,delivering:today.filter(order=>order.status==='配送中'&&!order.fulfillmentHoldReason).length,completed:today.filter(order=>order.status==='已完成').length,barrels:today.reduce((sum,order)=>sum+Number(order.quantity||0),0)}},
		messages(){const labels={seed:'历史订单',create:'客户下单',pay:'客户已支付','pay-balance':'客户余额支付','pay-wechat':'客户微信支付','pay-ticket':'水票全额抵扣','confirm-cod':'货到付款已确认',assign:'后台派单给你',accept:'你已接单','collect-tickets':'上门收取水票',complete:'签收完成','cod-collected':'货到付款已收款',cancel:'订单已取消','auto-cancel':'超时未支付关闭','create-replacement':'售后补送单','refund-stop-delivery':'退款停止配送','return-hold-delivery':'退货暂停配送'};const list=[];for(const order of this.orders){for(const event of order.timeline||[]){list.push({key:`${order.id}-${event.at}-${event.action}`,orderId:order.id,customer:order.customer,title:labels[event.action]||event.action,status:event.status,at:event.at,time:this.formatTime(event.at)})}}return list.sort((a,b)=>String(b.at).localeCompare(String(a.at))).slice(0,30)}},
	watch:{screen(value){if(value==='alert')this.startCountdown();else this.stopCountdown()}},
	onLoad(query){if(query&&query.screen)this.screen=query.screen==='call'?'workbench':query.screen;waterApi.getConfig().then(config=>{this.appConfig=config});if(this.screen!=='login'){if(waterApi.hasSession('courier'))this.syncCourierProfile().then(()=>this.startSync()).catch(error=>{if([401,403].includes(error.statusCode))waterApi.clearLocalSession('courier');this.screen='login';this.toast(error.message)});else this.screen='login'}if(this.screen==='alert')this.startCountdown()},
	onShow(){this.$nextTick(() => { const header = /** @type {{ refresh?: () => void }} */ (this.$refs.mobileHeader); header?.refresh?.() });if(this.screen!=='login')this.startSync()},
	onUnload(){this.stopSync();this.stopCountdown()},
	methods:{
		open(name){this.screen=name;uni.pageScrollTo({scrollTop:0,duration:0});if(name==='login')this.stopSync();else this.startSync()},goBack(){this.open(this.screen==='sign'?'delivery-detail':'workbench')},
		toast(title){uni.showToast({title,icon:'none'})},formatTime(value){const date=new Date(value);return Number.isNaN(date.getTime())?'--:--':`${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')} ${String(date.getHours()).padStart(2,'0')}:${String(date.getMinutes()).padStart(2,'0')}`},
		async login(){if(this.loginLoading)return;if(!/^1[3-9]\d{9}$/.test(this.phone))return this.toast('请输入 11 位已绑定手机号');this.loginLoading=true;try{this.appConfig=await waterApi.getConfig();if(!this.appConfig.demoAuth&&this.password.length<6)throw new Error('请输入至少 6 位登录密码');const session=this.appConfig.demoAuth&&!this.password?await waterApi.login('courier',{phone:this.phone},true):await waterApi.loginWithPassword('courier',this.phone,this.password);this.courierProfile=session.profile||this.courierProfile;this.password='';await this.syncCourierProfile();await this.loadOrders();this.open(this.pendingOrder&&this.online?'alert':'workbench')}catch(error){this.toast(error.message)}finally{this.loginLoading=false}},
		logout(){uni.showModal({title:'退出登录',content:'系统会先暂停接单，再注销服务端会话；退出失败时可以重试',success:async result=>{if(!result.confirm)return;try{if(this.online)await waterApi.setCourierOnline(false);this.online=false;await waterApi.logout('courier')}catch(error){return this.toast(`退出未完成，请重试：${error.message}`)}this.orders=[];this.selectedOrder=null;this.knownPendingIds=[];this.courierProfile={name:'',station:'',phone:''};this.open('login')}})},
		async syncCourierProfile(){const profile=await waterApi.getCourierProfile();this.courierProfile=profile;this.online=Boolean(profile.online);return profile},
		async toggleOnline(event){if(this.updatingOnline)return;const previous=this.online;const requested=Boolean(event?.detail?.value);this.online=requested;this.updatingOnline=true;try{const profile=await waterApi.setCourierOnline(requested);this.courierProfile=profile;this.online=Boolean(profile.online);this.toast(this.online?'已在服务端恢复接单':'已在服务端暂停接单')}catch(error){this.online=previous;this.toast(`接单状态更新失败：${error.message}`)}finally{this.updatingOnline=false}},
		startCountdown(){this.stopCountdown();this.countdown=15;this.countdownTimer=setInterval(()=>{this.countdown-=1;if(this.countdown<=0){this.stopCountdown();if(this.screen==='alert')this.screen='workbench'}},1000)},stopCountdown(){if(this.countdownTimer){clearInterval(this.countdownTimer);this.countdownTimer=null}},
		mapOrder(order,index){return{...order,index:index+1,timeLabel:this.formatTime(order.createdAt)}},
		async loadOrders(notify=false){try{const data=await waterApi.listCourierOrders();const mapped=data.map((order,index)=>this.mapOrder(order,index));const pendingIds=mapped.filter(order=>order.status==='待配送'&&!order.fulfillmentHoldReason).map(order=>order.id);const hasNew=pendingIds.some(id=>!this.knownPendingIds.includes(id));this.orders=mapped;if(this.selectedOrder){const latest=mapped.find(order=>order.id===this.selectedOrder.id);if(latest)this.selectedOrder=latest}if(hasNew&&this.online&&this.knownPendingIds.length&&this.screen==='workbench')this.screen='alert';this.knownPendingIds=pendingIds;if(notify)this.toast('订单已同步')}catch(error){console.warn('[delivery-sync]',error.message)}},
		startSync(){this.stopSync();this.loadOrders();this.refreshTimer=setInterval(()=>this.loadOrders(),3000)},stopSync(){if(this.refreshTimer){clearInterval(this.refreshTimer);this.refreshTimer=null}},selectOrder(order){this.selectedOrder=order;this.open('delivery-detail')},
		async acceptOrder(){const order=this.pendingOrder;if(!order)return this.toast('暂无待接订单');try{const updated=await waterApi.acceptOrder(order.id);this.selectedOrder=this.mapOrder(updated,0);this.toast('接单成功，用户端已同步');await this.loadOrders();this.open('delivery-detail')}catch(error){this.toast(error.message)}},
		openTicketSign(){const order=this.orders.find(item=>item.status==='配送中'&&item.payment==='货到付款'&&item.payStatus==='未支付'&&item.orderType!=='补送');if(!order)return this.toast('只有配送中、未付款的货到付款订单可以上门收票');this.selectedOrder=order;this.resetTickets();this.signMethod='ticket';this.open('sign')},
		resetTickets(){this.collectTickets=[];this.ticketPreview=null;this.ticketCode=''},
		/** 录入一张水票并向服务端试算收票后的应收；校验失败的票不会加入 */
		async addTicket(){const code=this.ticketCode.trim().toUpperCase();if(!code)return this.toast('请输入或扫描水票编码');if(this.collectTickets.some(item=>item.code===code))return this.toast('这张水票已添加');const order=this.activeOrder;if(!order)return this.toast('暂无可签收订单');const next=[...this.collectTickets,{type:this.ticketType,code}];this.ticketChecking=true;try{this.ticketPreview=await waterApi.courierPreviewTickets({orderId:order.id,tickets:next});this.collectTickets=next;this.ticketCode=''}catch(error){this.toast(error.message)}finally{this.ticketChecking=false}},
		async removeTicket(index){this.collectTickets.splice(index,1);if(!this.collectTickets.length){this.ticketPreview=null;return}try{this.ticketPreview=await waterApi.courierPreviewTickets({orderId:this.activeOrder.id,tickets:this.collectTickets})}catch(error){this.ticketPreview=null;this.toast(error.message)}},
		scanTicketCode(){if(typeof uni.scanCode!=='function')return this.toast('当前环境不支持扫码，请手动输入');uni.scanCode({scanType:['qrCode','barCode'],success:result=>{this.ticketCode=String(result.result||'').trim();if(this.ticketCode)this.addTicket()},fail:error=>{if(!/cancel/i.test(String(error&&error.errMsg)))this.toast('扫码失败，请手动输入')}})},
		/** 导航：小程序有坐标时打开微信内置地图（可选导航 App）；H5 打开高德地图网页/App；无坐标时复制地址 */
		navigateToCustomer(){const order=this.activeOrder;if(!order)return this.toast('暂无配送订单');const lat=Number(order.lat);const lng=Number(order.lng);const hasCoords=order.lat!==null&&order.lng!==null&&Number.isFinite(lat)&&Number.isFinite(lng);let native=false
			// #ifdef MP-WEIXIN
			native=true
			// #endif
			if(native){if(hasCoords&&typeof uni.openLocation==='function')uni.openLocation({latitude:lat,longitude:lng,name:order.customer||'收货地址',address:order.address||'',scale:17,fail:()=>this.copyAddress(order)});else this.copyAddress(order);return}
			const url=hasCoords?`https://uri.amap.com/marker?position=${lng},${lat}&name=${encodeURIComponent(order.address||'收货地址')}&coordinate=gaode&callnative=1`:`https://uri.amap.com/search?keyword=${encodeURIComponent(order.address||'')}&callnative=1`
			if(typeof window!=='undefined'&&typeof window.open==='function')window.open(url,'_blank');else this.copyAddress(order)},
		copyAddress(order){if(!order?.address)return this.toast('订单没有收货地址');uni.setClipboardData({data:order.address,success:()=>uni.showModal({title:'地址已复制',content:'该订单暂无定位坐标，已复制收货地址，可粘贴到地图 App 中导航。',showCancel:false})})},
		scanReceiptCode(){if(typeof uni.scanCode!=='function')return this.toast('当前环境不支持扫码，请手动输入');uni.scanCode({scanType:['qrCode'],success:result=>{this.receiptCode=String(result.result||'').replace(/\D/g,'').slice(-6)},fail:error=>{if(!/cancel/i.test(String(error&&error.errMsg)))this.toast('扫码失败，请手动输入')}})},
		callCustomer(){const phone=String(this.activeOrder?.phone||'').replace(/\D/g,'');if(phone.length!==11||typeof uni.makePhoneCall!=='function')return this.toast('订单没有可直接拨打的完整手机号');uni.makePhoneCall({phoneNumber:phone,fail:error=>{if(!/cancel/i.test(String(error&&error.errMsg)))this.toast('拨号失败')}})},
		chooseProof(){if(typeof uni.chooseImage!=='function')return this.toast('当前环境不支持选择照片');uni.chooseImage({count:1,sizeType:['compressed'],sourceType:['camera','album'],success:result=>{this.proofLocalPath=result.tempFilePaths?.[0]||''},fail:error=>{if(!/cancel/i.test(String(error&&error.errMsg)))this.toast('照片选择失败')}})},
		async finishSign(){if(this.signing)return;if(!this.confirmed)return this.toast('请确认已完成送达');if(!this.activeOrder)return this.toast('暂无可签收订单');if(this.activeOrder.fulfillmentHoldReason)return this.toast(this.activeOrder.fulfillmentHoldReason);if(this.signMethod==='ticket'&&!this.ticketSignAvailable)return this.toast('已付款订单不能再收水票，请选择其他签收方式');if(this.signMethod==='ticket'&&!this.collectTickets.length)return this.toast('请先添加要回收的水票');if(this.signMethod==='scan'&&!/^\d{6}$/.test(this.receiptCode.trim()))return this.toast('请输入或扫描 6 位签收码');this.signing=true;try{let order=this.activeOrder;if(order.status==='待配送')order=await waterApi.acceptOrder(order.id);if(order.status!=='配送中')return this.toast('仅配送中订单可签收');let proofUrl='';if(this.proofLocalPath){const uploaded=await waterApi.uploadImage(this.proofLocalPath,'courier');proofUrl=uploaded.url}const payload={signMethod:this.signMethod,proofUrl:proofUrl||undefined};if(this.signMethod==='ticket')payload.tickets=this.collectTickets;if(this.signMethod==='scan')payload.receiptCode=this.receiptCode.trim();const updated=await waterApi.completeOrder(order.id,payload);this.selectedOrder=this.mapOrder(updated,0);this.proofLocalPath='';this.resetTickets();this.receiptCode='';this.toast(this.signMethod==='ticket'?`水票已核销，签收完成，应收 ¥${Number(updated.amount||0).toFixed(2)}`:this.signMethod==='scan'?'签收码校验通过，签收完成':'签收完成，三端状态已同步');this.signMethod='manual';await this.loadOrders();setTimeout(()=>this.open('workbench'),600)}catch(error){this.toast(error.message)}finally{this.signing=false}},
		navChange(name){if(['workbench','orders','messages','mine'].includes(name))this.open(name)},
	}
}
</script>

